PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('student','instructor','admin')), auth_subject TEXT UNIQUE NOT NULL, locale TEXT NOT NULL DEFAULT 'en');
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (account_id TEXT REFERENCES accounts(id), organization_id TEXT REFERENCES organizations(id), role TEXT NOT NULL, PRIMARY KEY(account_id,organization_id));
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS specialties (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS instructors (id TEXT PRIMARY KEY, account_id TEXT UNIQUE REFERENCES accounts(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS instructor_drafts (account_id TEXT PRIMARY KEY REFERENCES accounts(id), data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','needs_changes')), revision INTEGER NOT NULL DEFAULT 1, submitted_at INTEGER, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS instructor_subjects (instructor_id TEXT REFERENCES instructors(id), subject_id TEXT REFERENCES subjects(id), approval TEXT NOT NULL CHECK(approval IN ('pending','approved','rejected','sample')), qualifications TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(instructor_id,subject_id));
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, version TEXT UNIQUE NOT NULL, approved INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS offerings (id TEXT PRIMARY KEY, instructor_id TEXT NOT NULL, subject_id TEXT NOT NULL, policy_id TEXT REFERENCES policies(id), data TEXT NOT NULL, FOREIGN KEY(instructor_id,subject_id) REFERENCES instructor_subjects(instructor_id,subject_id));
CREATE TABLE IF NOT EXISTS slots (id TEXT PRIMARY KEY, instructor_id TEXT NOT NULL REFERENCES instructors(id), starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL, timezone TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, CHECK(ends_at > starts_at));
CREATE TABLE IF NOT EXISTS slot_offerings (slot_id TEXT REFERENCES slots(id), offering_id TEXT REFERENCES offerings(id), PRIMARY KEY(slot_id,offering_id));
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES accounts(id), instructor_id TEXT NOT NULL REFERENCES instructors(id), offering_id TEXT NOT NULL REFERENCES offerings(id), slot_id TEXT NOT NULL REFERENCES slots(id), organization_id TEXT REFERENCES organizations(id), status TEXT NOT NULL CHECK(status IN ('held','confirmed','completed','expired','payment_failed','reconciliation','cancelled')), starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, goal TEXT NOT NULL, timezone TEXT NOT NULL, locale TEXT NOT NULL, quote TEXT NOT NULL, policy_snapshot TEXT NOT NULL, offering_snapshot TEXT NOT NULL, idempotency_key TEXT NOT NULL, provider_session TEXT UNIQUE, created_at INTEGER NOT NULL, UNIQUE(student_id,idempotency_key));
CREATE INDEX IF NOT EXISTS booking_overlap ON bookings(instructor_id,starts_at,ends_at,status);
CREATE TABLE IF NOT EXISTS payment_events (provider_event_id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), kind TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, transaction_id TEXT, occurred_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS unique_successful_charge ON payment_events(transaction_id) WHERE kind='paid';
CREATE TABLE IF NOT EXISTS booking_events (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), actor_id TEXT REFERENCES accounts(id), kind TEXT NOT NULL, data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), recipient_id TEXT NOT NULL REFERENCES accounts(id), kind TEXT NOT NULL, locale TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, UNIQUE(booking_id,recipient_id,kind));
CREATE TABLE IF NOT EXISTS payouts (id TEXT PRIMARY KEY, booking_id TEXT UNIQUE NOT NULL REFERENCES bookings(id), instructor_id TEXT NOT NULL REFERENCES instructors(id), status TEXT NOT NULL DEFAULT 'policy_pending', data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, booking_id TEXT UNIQUE NOT NULL REFERENCES bookings(id), student_id TEXT NOT NULL REFERENCES accounts(id), instructor_id TEXT NOT NULL REFERENCES instructors(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, moderation TEXT NOT NULL DEFAULT 'pending' CHECK(moderation IN ('pending','published','hidden')), created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS review_replies (id TEXT PRIMARY KEY, review_id TEXT UNIQUE NOT NULL REFERENCES reviews(id), instructor_id TEXT NOT NULL REFERENCES instructors(id), body TEXT NOT NULL, moderation TEXT NOT NULL DEFAULT 'pending' CHECK(moderation IN ('pending','published','hidden')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS content_reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES accounts(id), review_id TEXT REFERENCES reviews(id), reply_id TEXT REFERENCES review_replies(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', CHECK((review_id IS NULL) != (reply_id IS NULL)));
-- Future features, not public V1 endpoints. Personal data stays server-side.
CREATE TABLE IF NOT EXISTS saved_instructors (account_id TEXT REFERENCES accounts(id), instructor_id TEXT REFERENCES instructors(id), PRIMARY KEY(account_id,instructor_id));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES accounts(id), instructor_id TEXT NOT NULL REFERENCES instructors(id), booking_id TEXT REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), sender_id TEXT NOT NULL REFERENCES accounts(id), body TEXT NOT NULL, moderation TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS learning_requests (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES accounts(id), subject_id TEXT NOT NULL REFERENCES subjects(id), data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, booking_id TEXT REFERENCES bookings(id), owner_id TEXT NOT NULL REFERENCES accounts(id), storage_key TEXT NOT NULL, mime_type TEXT NOT NULL, scan_status TEXT NOT NULL DEFAULT 'quarantined');
CREATE TABLE IF NOT EXISTS promotions (id TEXT PRIMARY KEY, data TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0);
